    public string? BotId { get; private init; }

    /// <summary>
    /// The version of the bot associated with the slot. Constraints: o min: 5 o max: 5 o pattern: ^DRAFT$
    /// </summary>
    [CliOption("--bot-version")]
    public string? BotVersion { get; private init; }

    /// <summary>
    /// The identifier of the language and locale that the slot will be used in. The string must match one of the supported locales. All of the bots, intents, slot types used by the slot must have the same lo- cale. For more information, see Supported languages .
    /// </summary>
    [CliOption("--locale-id")]
    public string? LocaleId { get; private init; }

    /// <summary>
    /// The identifier of the intent that contains the slot. Constraints: o min: 10 o max: 10 o pattern: ^[0-9a-zA-Z]+$
    /// </summary>
    [CliOption("--intent-id")]
    public string? IntentId { get; private init; }

    /// <summary>
    /// A description of the slot. Use this to help identify the slot in lists. Constraints: o min: 0 o max: 2000
    /// </summary>
    [CliOption("--description")]
    public string? Description { get; set; }

    /// <summary>
    /// The unique identifier for the slot type associated with this slot. The slot type determines the values that can be entered into the slot. Constraints: o min: 1 o max: 25 o pattern: ^((AMAZON\.)[a-zA-Z_]+?|[0-9a-zA-Z]+)$
    /// </summary>
    [CliOption("--slot-type-id")]
    public string? SlotTypeId { get; set; }

    /// <summary>
    /// Determines how slot values are used in Amazon CloudWatch logs. If the value of the obfuscationSetting parameter is DefaultObfuscation , slot values are obfuscated in the log output. If the value is None , the actual value is present in the log output. The default is to obfuscate values in the CloudWatch logs. obfuscationSettingType -&gt; (string) [required] Value that determines whether Amazon Lex obscures slot values in conversation logs. The default is to obscure the values. Possible values: o None o DefaultObfuscation Shorthand Syntax: obfuscationSettingType=string JSON Syntax: { "obfuscationSettingType": "None"|"DefaultObfuscation" }
    /// </summary>
    [CliOption("--obfuscation-setting")]
    public string? ObfuscationSetting { get; set; }

    /// <summary>
    /// Indicates whether the slot returns multiple values in one response. Multi-value slots are only available in the en-US locale. If you set this value to true in any other locale, Amazon Lex throws a Valida- tionException . If the multipleValuesSetting is not set, the default value is false . allowMultipleValues -&gt; (boolean) Indicates whether a slot can return multiple values. When true , the slot may return more than one value in a response. When false , the slot returns only a single value. Multi-value slots are only available in the en-US locale. If you set this value to true in any other locale, Amazon Lex throws a ValidationException . If the allowMutlipleValues is not set, the default value is false . Shorthand Syntax: allowMultipleValues=boolean JSON Syntax: { "allowMultipleValues": true|false }
    /// </summary>
    [CliOption("--multiple-values-setting")]
    public string? MultipleValuesSetting { get; set; }

    /// <summary>
